/**
 * What the mock chart server needs from an app's market simulator: its instruments, bars at three base
 * resolutions (tiers.ts), and the last value of a symbol. The app's simulator implements it; nothing in this
 * package knows what the instruments are.
 */
import type { Tier } from './tiers';
export interface MockInstrument {
    sym: string;
    /** '%' (yields) and 'bp' (spreads) are additive: changes, not returns; realized vol in bp */
    unit: string;
    tick?: number | null;
    hasVolume: boolean;
    /** dollars per point (futures), for backtests' P&L */
    multiplier?: number;
    /** set on instruments made from a typed expression (a spread or ratio) */
    expr?: string;
}
export interface BarMarket {
    readonly inst: MockInstrument[];
    readonly index: Map<string, number>;
    /** every instrument's bars: 1-second (the last hour or two), 1-minute (days), daily (years) */
    readonly tiers: {
        s1: Tier;
        m1: Tier;
        d1: Tier;
    };
    has(sym: string): boolean;
    value(sym: string): number;
    instrument(sym: string): MockInstrument | undefined;
}
